function renderFilters(){filterHost.innerHTML=filters.map(([label,key])=>`<button class="filter ${activeFilter===key?'active':''}" data-filter="${key}">${label}</button>`).join('');filterHost.querySelectorAll('button').forEach(b=>b.onclick=()=>{activeFilter=b.dataset.filter;renderFilters();renderBooks()})}
function renderBooks(){const shown=books.filter(b=>activeFilter==='all'||categories[b.id]===activeFilter);document.querySelector('#bookCount').textContent=`${shown.length} illustrated adventure${shown.length===1?'':'s'}`;grid.innerHTML=shown.map(b=>`<button class="book-card" data-book="${b.id}" aria-label="Play ${b.title}"><span class="book-icon">${b.icon}</span><span class="book-title">${b.title}</span><span class="book-author">${b.author}</span><span class="book-tag">${b.genre}</span><span class="card-arrow">↗</span></button>`).join('');grid.querySelectorAll('.book-card').forEach(card=>card.onclick=()=>startBook(card.dataset.book))}
