function renderMeters(){const cap=Math.max(4,current.scenes.length+1);document.querySelector('#meters').innerHTML=Object.entries(statNames).map(([key,name])=>`<div class="meter"><div class="meter-head"><span>${name}</span><span>${stats[key]}</span></div><div class="meter-track"><div class="meter-fill" style="width:${Math.min(100,stats[key]/cap*100)}%"></div></div></div>`).join('')}
function renderScene(){const s=current.scenes[sceneIndex];document.querySelector('#actLabel').textContent=`Chapter ${sceneIndex+1} · ${current.scenes.length}`;document.querySelector('#artSymbol').textContent=current.icon;document.querySelector('#storyContent').innerHTML=`<div class="chapter-kicker">${current.genre} · a new page</div><h2>${s[0]}</h2><div class="story-copy">${s[1]}</div><div class="thought">${s[2]}</div><div class="choices">${s[3].map((c,i)=>`<button class="choice" data-choice="${i}"><span class="choice-num">${i===0?'A':'B'}</span><span class="choice-text">${c[0]}</span><span class="choice-hint">${c[1]}</span></button>`).join('')}</div>`;document.querySelectorAll('.choice').forEach(btn=>btn.onclick=()=>choose(Number(btn.dataset.choice)));renderMeters();const j=document.querySelector('#journal');j.innerHTML=`<strong>Your margin notes</strong>${notes.length?notes.slice(-2).map(n=>`<span>• ${n}</span>`).join('<br>'):'The first choice is still ahead.'}`;document.querySelector('#rollResult').textContent='Ready when you are'}
function choose(i){if(pending)return;const s=current.scenes[sceneIndex],c=s[3][i],stat=traitStat[c[2]]||'heart';stats[stat]++;notes.push(c[3]);pending={choice:c,stat};renderMeters();const die=document.querySelector('#die');die.classList.remove('rolling');void die.offsetWidth;die.classList.add('rolling');let ticks=0;const face=setInterval(()=>{die.textContent=1+Math.floor(Math.random()*20);ticks++;if(ticks>8)clearInterval(face)},75);const roll=1+Math.floor(Math.random()*20),bonus=Math.min(3,Math.floor(stats[stat]/2)),total=roll+bonus;pending.roll=roll;pending.total=total;setTimeout(()=>{die.classList.remove('rolling');die.textContent=roll;const degree=roll<=5?'A difficult turn':roll>=16?'A fortunate turn':'A complicated turn';document.querySelector('#rollResult').textContent=`d20 · ${roll}${bonus?` + ${bonus} ${statNames[stat]}`:''} = ${total}`;document.querySelector('#modalDie').textContent=roll>=16?'✦':roll<=5?'◌':'🎲';document.querySelector('#modalTitle').textContent=degree;document.querySelector('#modalText').textContent=roll>=16?`Your ${c[1].toLowerCase()} meets a lucky opening. ${c[3]} The story bends, but your choice is what gives the moment meaning.`:roll<=5?`The path answers with a complication—not a dead end. ${c[3]} You can still decide how to meet what follows.`:`The moment stays uncertain. ${c[3]} The next step is yours to shape.`;document.querySelector('#dieModal').classList.add('show');if(soundOn)playChime(roll)},700)}
