function showEnding(){const best=Object.keys(stats).sort((a,b)=>stats[b]-stats[a])[0],qualities={heart:['a generous listener','Your attention became a shelter. You made room for other people’s truths, and that is a kind of courage.'],nerve:['a brave questioner','You chose not to let fear make every decision. Courage, here, meant staying answerable to what came next.'],insight:['a thoughtful witness','You looked past easy stories and asked what was really happening. Seeing clearly is one way to care.']};const [identity,reflection]=qualities[best];const storyEnd=current.scenes.at(-1),summary=storyEnd[2];document.querySelector('#actLabel').textContent='The end—for now';document.querySelector('#artSymbol').textContent=current.icon;document.querySelector('#storyContent').innerHTML=`<span class="ending-badge">Your ending · ${identity}</span><h2>The story stays with you.</h2><div class="story-copy">${reflection} In <em>${current.title}</em>, you chose <strong>${notes.length?notes[notes.length-1].toLowerCase():'your own way'}</strong>. The page closes, but the question remains: “${summary}”</div><div class="thought">${notes.length?notes.join(' '):'Every ending is also an invitation to begin again.'}</div><button class="restart-btn" id="replayBtn">↻ Play this story again</button>`;document.querySelector('#replayBtn').onclick=()=>startBook(current.id);document.querySelector('#rollResult').textContent=`Journey complete · ${notes.length} choices`;document.querySelector('#journal').innerHTML=`<strong>Your margin notes</strong>${notes.slice(-2).join('<br>')}`;renderMeters();let completed=[];try{completed=JSON.parse(localStorage.getItem('marginalia-completed')||'[]')}catch{}if(!completed.includes(current.id)){completed.push(current.id);try{localStorage.setItem('marginalia-completed',JSON.stringify(completed))}catch{}}pending=null}
function playChime(n){try{audioCtx=audioCtx||new (window.AudioContext||window.webkitAudioContext)();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='sine';osc.frequency.value=300+n*16;gain.gain.setValueAtTime(.08,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.35);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+.36)}catch{}}
document.querySelector('#continueBtn').onclick=advance;document.querySelector('#dieModal').onclick=e=>{if(e.target.id==='dieModal')advance()};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('#dieModal').classList.contains('show'))advance()});document.querySelector('#backBtn').onclick=()=>{document.querySelector('#gameView').style.display='none';document.querySelector('#libraryView').style.display='block';document.querySelector('#dieModal').classList.remove('show');pending=null;window.scrollTo({top:0,behavior:'smooth'})};document.querySelector('#libraryBtn').onclick=()=>document.querySelector('#backBtn').click();document.querySelector('#soundToggle').onclick=e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫ Sound on':'♫ Sound off';e.currentTarget.setAttribute('aria-pressed',String(soundOn))};renderFilters();renderBooks();
